package com.ftk.tpip.control.api.release;
import static org.junit.jupiter.api.Assertions.*;import org.junit.jupiter.api.Test;import org.springframework.web.bind.annotation.*;
class GlobalImpactJobSchedulingControllerContractTest{
 @Test void exposesRuntimeStallSloAndPriorityContracts()throws Exception{String base=GlobalImpactJobSchedulingController.class.getAnnotation(RequestMapping.class).value()[0];assertEquals("/{jobId}/runtime-state",GlobalImpactJobSchedulingController.class.getMethod("state",String.class).getAnnotation(GetMapping.class).value()[0]);assertEquals("/stalled",GlobalImpactJobSchedulingController.class.getMethod("stalled",int.class).getAnnotation(GetMapping.class).value()[0]);assertEquals("/slo-summary",GlobalImpactJobSchedulingController.class.getMethod("summary",int.class).getAnnotation(GetMapping.class).value()[0]);assertEquals("/control/v1/verification-drift-workbench/global-governance-policy-impact-jobs/{jobId}:reprioritize",base+GlobalImpactJobSchedulingController.class.getMethod("reprioritize",String.class,GlobalImpactJobSchedulingController.Reprioritize.class,String.class).getAnnotation(PostMapping.class).value()[0]);}}
